def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_op = history[-1]

    opp_c = 0
    for h in history:
        if h[1] == 'C':
            opp_c += 1
    opp_d = n - opp_c

    w10 = n if n < 10 else 10
    recent_opp_c = 0
    for i in range(n - w10, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
    recent_rate = recent_opp_c / w10

    def_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            def_run += 1
        else:
            break

    coop_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            coop_run += 1
        else:
            break

    mutual_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            mutual_run += 1
        else:
            break

    prev_d = 0
    nonpun = 0
    punish = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            prev_d += 1
            if history[i][1] == 'C':
                nonpun += 1
            else:
                punish += 1

    second_chance = (
        last_op == 'D'
        and last_me == 'C'
        and n >= 2
        and history[-2][0] == 'D'
        and history[-2][1] == 'D'
    )

    last_attempt = -1
    for i in range(n - 1, -1, -1):
        if (
            history[i][0] == 'C'
            and history[i][1] == 'D'
            and i > 0
            and history[i - 1][1] == 'D'
        ):
            last_attempt = i
            break

    suppress = False
    if last_attempt >= 0 and not second_chance:
        has_opp_c = False
        for j in range(last_attempt + 1, n):
            if history[j][1] == 'C':
                has_opp_c = True
                break
        if not has_opp_c:
            suppress = True

    if last_op == 'D':
        # If this looks like a short alternation after one of our Ds, try to settle.
        if (
            last_me == 'C'
            and def_run == 1
            and n >= 2
            and history[-2][0] == 'D'
            and history[-2][1] == 'C'
        ):
            return 'C'

        # Immediate second chance after an escape from mutual defection.
        if second_chance:
            return 'C'

        # Break long mutual-defection loops, but stop probing if it clearly failed.
        if mutual_run >= 5 and not suppress:
            return 'C'

        return 'D'

    # If the opponent is mostly hostile now, a single C is often bait.
    if opp_d > opp_c + 3 and recent_rate <= 0.5:
        return 'D'

    if recent_rate <= 0.35 and opp_c <= opp_d:
        return 'D'

    # Safe exploitation only after repeated evidence that defections are not punished.
    exploit_prob = 0.0
    if recent_rate >= 0.65:
        if punish == 0:
            if nonpun >= 4:
                exploit_prob = 0.65
            elif nonpun >= 2:
                exploit_prob = 0.40
            elif nonpun >= 1:
                exploit_prob = 0.15
        elif prev_d >= 4 and nonpun * 10 >= prev_d * 6:
            exploit_prob = 0.20

    if exploit_prob > 0.0:
        if rng.random() < exploit_prob:
            return 'D'
        if n >= 95 and exploit_prob >= 0.35:
            return 'D'

    return 'C'
